const TR={type:"DISSOLVE",duration:0.25,easing:{type:"EASE_IN_AND_OUT"}};
function nav(node,destId){if(!node)return false;const has=node.reactions.some(r=>r.actions.some(a=>a.destinationId===destId));if(!has)node.reactions=[...node.reactions,{trigger:{type:"ON_CLICK"},actions:[{type:"NODE",navigation:"NAVIGATE",destinationId:destId,transition:TR}]}];return true;}
function hotspot(parent,x,y,w,h,name,destId){let r=parent.findOne(n=>n.name===name);if(!r){r=figma.createRectangle();r.resize(w,h);r.fills=[];r.name=name;parent.appendChild(r);r.x=x;r.y=y;}nav(r,destId);return r;}
